// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, uint256 gasLimit) public {
        vm.assume(value <= address(this).balance);
        vm.assume(gasLimit >= 2300 && gasLimit <= 100000);
        GasSink target = new GasSink();
        target.setGasToConsume(gasLimit);
        vm.deal(address(c), value);
        bool ok;
        try c.sendMoney(address(target), value) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract GasSink {
    uint256 gasToConsume;
    function setGasToConsume(uint256 g) external { gasToConsume = g; }
    receive() external payable {
        uint256 start = gasleft();
        while (start - gasleft() < gasToConsume) {}
    }
}
